/**
 * "Blocked by" links between issues. Each row is one `issueId -> blockerId` edge; the pair is the key.
 *
 * Must call (do not reimplement): orgPredicate, livePredicate, listLabelsForIssues
 */
import { and, asc, eq, inArray, notInArray } from "drizzle-orm";
import { getDb, issueDependencies, issues } from "@/server/db";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import { brandId, toIssue, toIssueDependency } from "./_mappers";
import { livePredicate, orgPredicate } from "./base-repository";
import { listLabelsForIssues } from "./label-repository";
import type { SQL } from "drizzle-orm";
import type { IsoTimestamp, IssueId, OrgId, UserId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";

function linkPredicate(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): SQL | undefined {
  return and(
    orgPredicate(issueDependencies.orgId, orgId),
    eq(issueDependencies.issueId, issueId),
    eq(issueDependencies.blockerId, blockerId),
  );
}

/**
 * Stores `issueId` as blocked by `blockerId`, or returns the link already
 * stored. Resolves `null` when the new edge would close a loop, which includes
 * an issue blocking itself.
 *
 * The existence check, the reachability walk and the insert run in one
 * synchronous transaction, so two concurrent requests cannot both pass the
 * walk and then both write.
 */
export async function insertLinkUnlessCyclic(input: {
  readonly orgId: OrgId;
  readonly issueId: IssueId;
  readonly blockerId: IssueId;
  readonly createdBy: UserId;
  readonly createdAt: IsoTimestamp;
}): Promise<IssueDependency | null> {
  return getDb().transaction((tx) => {
    const existing = tx
      .select()
      .from(issueDependencies)
      .where(linkPredicate(input.orgId, input.issueId, input.blockerId))
      .get();
    if (existing) return toIssueDependency(existing);

    // Walk the "blocked by" edges upward from the proposed blocker. Reaching
    // the blocked issue means the new edge would close a loop.
    const seen = new Set<string>();
    let frontier: readonly string[] = [input.blockerId];
    while (frontier.length > 0) {
      if (frontier.includes(input.issueId)) return null;
      for (const id of frontier) seen.add(id);

      const upstream = tx
        .select({ blockerId: issueDependencies.blockerId })
        .from(issueDependencies)
        .where(
          and(
            orgPredicate(issueDependencies.orgId, input.orgId),
            inArray(issueDependencies.issueId, [...frontier]),
          ),
        )
        .all();
      frontier = [...new Set(upstream.map((row) => row.blockerId))].filter(
        (id) => !seen.has(id),
      );
    }

    const row = tx
      .insert(issueDependencies)
      .values({
        orgId: input.orgId,
        issueId: input.issueId,
        blockerId: input.blockerId,
        createdBy: input.createdBy,
        createdAt: input.createdAt,
      })
      .returning()
      .get();

    return toIssueDependency(row);
  });
}

/** Resolves `true` only when a link row was actually deleted. */
export async function deleteLink(
  orgId: OrgId,
  issueId: IssueId,
  blockerId: IssueId,
): Promise<boolean> {
  const result = getDb()
    .delete(issueDependencies)
    .where(linkPredicate(orgId, issueId, blockerId))
    .run();
  return result.changes > 0;
}

/**
 * Live blocker rows of `issueId`, in issue-number order. `openOnly` also drops
 * blockers that are done or canceled.
 */
function liveBlockerRows(orgId: OrgId, issueId: IssueId, openOnly: boolean) {
  return getDb()
    .select({ issue: issues })
    .from(issueDependencies)
    .innerJoin(issues, eq(issues.id, issueDependencies.blockerId))
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.issueId, issueId),
        orgPredicate(issues.orgId, orgId),
        livePredicate(issues.archivedAt, {}),
        openOnly
          ? notInArray(issues.status, [...CLOSED_ISSUE_STATUSES])
          : undefined,
      ),
    )
    .orderBy(asc(issues.number), asc(issues.id))
    .all();
}

/** Live blockers of `issueId` that are still open, in issue-number order. */
export async function listOpenBlockerIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly IssueId[]> {
  return liveBlockerRows(orgId, issueId, true).map((row) =>
    brandId<IssueId>(row.issue.id),
  );
}

/** Live blockers of `issueId` in any status, in issue-number order. */
export async function listLiveBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const rows = liveBlockerRows(orgId, issueId, false);
  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => brandId<IssueId>(row.issue.id)),
  );

  return rows.map(({ issue }) =>
    toIssue(issue, (labels[issue.id] ?? []).map((label) => label.id)),
  );
}

/** Every issue that `blockerId` is holding back, including archived ones. */
export async function listBlockedIssueIds(
  orgId: OrgId,
  blockerId: IssueId,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ issueId: issueDependencies.issueId })
    .from(issueDependencies)
    .where(
      and(
        orgPredicate(issueDependencies.orgId, orgId),
        eq(issueDependencies.blockerId, blockerId),
      ),
    )
    .all();

  return rows.map((row) => brandId<IssueId>(row.issueId));
}

