/**
 * "Blocked by" links between issues. Writes are an `issue:update` on the blocked issue; the completion gate itself lives in `issue-service`.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, requireFound
 */
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueDependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { DependencyCycleError, issueResource, requireFound } from "./_support";
import { toIsoTimestamp } from "@/types/common";
import type { IssueId, OrgId } from "@/types/common";
import type { Issue, IssueDependency } from "@/types/issue";
import type { Actor } from "@/types/member";

/** Raised when a status change to `done` is refused. `blockerIds` lists exactly the open blockers. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(
      `Issue cannot be completed while ${blockerIds.length} blocker(s) are still open`,
    );
    this.name = "IssueBlockedError";
  }
}

/**
 * Records that `issueId` is blocked by `blockerId`. Adding a link that already
 * exists returns the stored link and writes nothing.
 */
export async function addBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const blocked = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(blocked));
  assertNotArchived("Issue", blocked.id, blocked);
  assertNotArchived("Issue", blocker.id, blocker);

  if (input.issueId === input.blockerId) {
    throw new DependencyCycleError(input.issueId, input.blockerId);
  }

  const link = await issueDependencyRepo.insertLinkUnlessCyclic({
    orgId: input.orgId,
    issueId: input.issueId,
    blockerId: input.blockerId,
    createdBy: actor.userId,
    createdAt: toIsoTimestamp(new Date()),
  });
  if (link === null) {
    throw new DependencyCycleError(input.issueId, input.blockerId);
  }

  return link;
}

/** Deletes the link. Resolves `false` when there was no such link. Only the blocked issue must exist. */
export async function removeBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const blocked = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(blocked));

  return issueDependencyRepo.deleteLink(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

/** The non-archived blockers of `issueId`, open or closed, in issue-number order. */
export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueDependencyRepo.listLiveBlockers(orgId, issueId);
}

