/**
 * When a blocker closes, tells the assignee of each issue it was holding back
 * once nothing blocks that issue any more.
 *
 * Must call (do not reimplement): subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import * as issueDependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { notify } from "./notification-service";
import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { IssueId, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { IssueStatus } from "@/types/issue";

/** Attached once from `event-registry`; the returned function detaches both handlers. */
export function registerIssueDependencyListeners(): Unsubscribe {
  const offStatusChanged = subscribe("issue.status_changed", async (payload) => {
    if (isClosed(payload.from) || !isClosed(payload.to)) return;
    await notifyUnblockedIssues(payload.orgId, payload.issueId, payload.actorId);
  });

  const offArchived = subscribe("issue.archived", async (payload) => {
    // Archiving leaves `status` untouched, so the stored status is the one the
    // blocker had just before it was archived.
    const blocker = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (blocker === null || isClosed(blocker.status)) return;
    await notifyUnblockedIssues(payload.orgId, payload.issueId, payload.actorId);
  });

  return () => {
    offStatusChanged();
    offArchived();
  };
}

async function notifyUnblockedIssues(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: UserId | null,
): Promise<void> {
  const blockedIds = await issueDependencyRepo.listBlockedIssueIds(orgId, blockerId);

  for (const blockedId of blockedIds) {
    const blocked = await issueRepo.findIssueById(orgId, blockedId);
    if (blocked === null || blocked.assigneeId === null) continue;
    if (blocked.archivedAt !== null || isClosed(blocked.status)) continue;

    const stillBlocked = await issueDependencyRepo.listOpenBlockerIds(orgId, blockedId);
    if (stillBlocked.length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "An issue is unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

function isClosed(status: IssueStatus): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}

