import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { getDb, issueDependencies } from "@/server/db";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as depService from "@/server/services/issue-dependency-service";
import { IssueBlockedError } from "@/server/services/issue-dependency-service";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { IssueId, UserId } from "@/types/common";
import type { Issue } from "@/types/issue";

let cleanup: () => void;
let t: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  t = await createTenant("depsacme");
  other = await createTenant("depsother");
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

async function make(title: string, assigneeId: UserId | null = null): Promise<Issue> {
  return issueService.createIssue(
    t.actors.owner,
    issueInput(t.org.id, t.project.id, { title, assigneeId }),
  );
}

async function unblockedFor(recipientId: UserId, issueId: IssueId) {
  const page = await notificationRepo.listNotifications({
    orgId: t.org.id,
    recipientId,
    unreadOnly: false,
    limit: 100,
    cursor: null,
    kind: ["issue_unblocked"],
  });
  return page.items.filter((n) => n.href === `/issues/${issueId}`);
}

const link = (issueId: IssueId, blockerId: IssueId) => ({
  orgId: t.org.id,
  issueId,
  blockerId,
});

describe("links", () => {
  it("stores a link stamped with the actor and returns the existing one on re-add", async () => {
    const a = await make("A");
    const b = await make("B");
    const first = await depService.addBlocker(t.actors.member, link(a.id, b.id));
    expect(first).toMatchObject({
      orgId: t.org.id,
      issueId: a.id,
      blockerId: b.id,
      createdBy: t.actors.member.userId,
    });
    const again = await depService.addBlocker(t.actors.owner, link(a.id, b.id));
    expect(again).toEqual(first);
    const rows = getDb().select().from(issueDependencies).all().filter((r) => r.issueId === a.id);
    expect(rows).toHaveLength(1);
    const blockers = await depService.listBlockers(t.actors.viewer, t.org.id, a.id);
    expect(blockers.map((i) => i.id)).toEqual([b.id]);
  });

  it("rejects self-blocks and direct/transitive cycles, storing nothing", async () => {
    const x = await make("X");
    const y = await make("Y");
    const z = await make("Z");
    await expect(depService.addBlocker(t.actors.owner, link(x.id, x.id))).rejects.toThrow();
    await depService.addBlocker(t.actors.owner, link(x.id, y.id));
    await expect(depService.addBlocker(t.actors.owner, link(y.id, x.id))).rejects.toThrow();
    await depService.addBlocker(t.actors.owner, link(y.id, z.id));
    await expect(depService.addBlocker(t.actors.owner, link(z.id, x.id))).rejects.toThrow();
    expect(await depService.listBlockers(t.actors.owner, t.org.id, z.id)).toEqual([]);
    expect(await depService.listBlockers(t.actors.owner, t.org.id, y.id)).toHaveLength(1);
  });

  it("rejects cross-org and unknown ids, storing nothing", async () => {
    const a = await make("cross A");
    const b = await make("cross B");
    await expect(
      depService.addBlocker(t.actors.owner, { orgId: other.org.id, issueId: a.id, blockerId: b.id }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      depService.addBlocker(other.actors.owner, { orgId: other.org.id, issueId: a.id, blockerId: b.id }),
    ).rejects.toMatchObject({ code: "not_found" });
    await expect(
      depService.addBlocker(t.actors.owner, link(a.id, "nope" as IssueId)),
    ).rejects.toMatchObject({ code: "not_found" });
    expect(await depService.listBlockers(t.actors.owner, t.org.id, a.id)).toEqual([]);
    expect(await depService.removeBlocker(t.actors.owner, link(a.id, "nope" as IssueId))).toBe(false);
  });

  it("requires edit permission on the blocked issue for add and remove, read for list", async () => {
    const a = await make("perm A");
    const b = await make("perm B");
    await expect(depService.addBlocker(t.actors.viewer, link(a.id, b.id))).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    await depService.addBlocker(t.actors.owner, link(a.id, b.id));
    await expect(depService.removeBlocker(t.actors.viewer, link(a.id, b.id))).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    expect(await depService.listBlockers(t.actors.viewer, t.org.id, a.id)).toHaveLength(1);
  });

  it("refuses archived issues on add, and removes once then reports false", async () => {
    const a = await make("arch A");
    const b = await make("arch B");
    await issueService.archiveIssue(t.actors.owner, t.org.id, b.id);
    await expect(depService.addBlocker(t.actors.owner, link(a.id, b.id))).rejects.toBeInstanceOf(
      AlreadyArchivedError,
    );

    const c = await make("rm C");
    const d = await make("rm D");
    await depService.addBlocker(t.actors.owner, link(c.id, d.id));
    expect(await depService.removeBlocker(t.actors.owner, link(c.id, d.id))).toBe(true);
    expect(await depService.removeBlocker(t.actors.owner, link(c.id, d.id))).toBe(false);
  });

  it("lists live blockers in issue-number order", async () => {
    const a = await make("ord A");
    const b = await make("ord B");
    const c = await make("ord C");
    await depService.addBlocker(t.actors.owner, link(a.id, c.id));
    await depService.addBlocker(t.actors.owner, link(a.id, b.id));
    expect((await depService.listBlockers(t.actors.owner, t.org.id, a.id)).map((i) => i.id)).toEqual([
      b.id,
      c.id,
    ]);
    await issueService.archiveIssue(t.actors.owner, t.org.id, c.id);
    expect((await depService.listBlockers(t.actors.owner, t.org.id, a.id)).map((i) => i.id)).toEqual([
      b.id,
    ]);
  });
});

describe("completion gate", () => {
  it("refuses done while a blocker is open, leaving status and events untouched", async () => {
    const a = await make("gate A");
    const b = await make("gate B");
    const c = await make("gate C");
    await depService.addBlocker(t.actors.owner, link(a.id, b.id));
    await depService.addBlocker(t.actors.owner, link(a.id, c.id));

    const seen: string[] = [];
    const off = subscribe("issue.status_changed", (p) => {
      seen.push(p.issueId);
    });

    const err = await issueService
      .changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: a.id, status: "done" })
      .catch((e: unknown) => e);
    expect(err).toBeInstanceOf(IssueBlockedError);
    expect([...(err as IssueBlockedError).blockerIds].sort()).toEqual([b.id, c.id].sort());
    expect((await issueService.getIssue(t.actors.owner, t.org.id, a.id)).issue.status).toBe("backlog");

    const moveErr = await issueService
      .moveIssue(t.actors.owner, { orgId: t.org.id, issueId: a.id, toStatus: "done", toIndex: 0 })
      .catch((e: unknown) => e);
    expect(moveErr).toBeInstanceOf(IssueBlockedError);

    await issueService.changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: a.id, status: "in_review" });
    expect(seen).toEqual([a.id]);
    off();

    await issueService.changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: b.id, status: "done" });
    const stillBlocked = await issueService
      .changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: a.id, status: "done" })
      .catch((e: unknown) => e);
    expect((stillBlocked as IssueBlockedError).blockerIds).toEqual([c.id]);

    await issueService.changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: c.id, status: "canceled" });
    const done = await issueService.changeIssueStatus(t.actors.owner, {
      orgId: t.org.id,
      issueId: a.id,
      status: "done",
    });
    expect(done.status).toBe("done");
  });
});

describe("unblocked notification", () => {
  it("notifies the assignee once when the last open blocker closes, not for closed-to-closed", async () => {
    const assignee = t.userIds.member;
    const blocked = await make("notif blocked", assignee);
    const b1 = await make("notif b1");
    const b2 = await make("notif b2");
    await depService.addBlocker(t.actors.owner, link(blocked.id, b1.id));
    await depService.addBlocker(t.actors.owner, link(blocked.id, b2.id));

    await issueService.changeIssueStatus(t.actors.admin, { orgId: t.org.id, issueId: b1.id, status: "done" });
    expect(await unblockedFor(assignee, blocked.id)).toHaveLength(0);

    await issueService.changeIssueStatus(t.actors.admin, { orgId: t.org.id, issueId: b2.id, status: "canceled" });
    const rows = await unblockedFor(assignee, blocked.id);
