    await depService.addBlocker(t.actors.owner, link(a.id, c.id));
    await depService.addBlocker(t.actors.owner, link(a.id, b.id));
    expect((await depService.listBlockers(t.actors.owner, t.org.id, a.id)).map((i) => i.id)).toEqual([
      b.id,
      c.id,
    ]);
    await issueService.archiveIssue(t.actors.owner, t.org.id, c.id);
    expect((await depService.listBlockers(t.actors.owner, t.org.id, a.id)).map((i) => i.id)).toEqual([
      b.id,
    ]);
  });
});

describe("completion gate", () => {
  it("refuses done while a blocker is open, leaving status and events untouched", async () => {
    const a = await make("gate A");
    const b = await make("gate B");
    const c = await make("gate C");
    await depService.addBlocker(t.actors.owner, link(a.id, b.id));
    await depService.addBlocker(t.actors.owner, link(a.id, c.id));

    const seen: string[] = [];
    const off = subscribe("issue.status_changed", (p) => {
      seen.push(p.issueId);
    });

    const err = await issueService
      .changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: a.id, status: "done" })
      .catch((e: unknown) => e);
    expect(err).toBeInstanceOf(IssueBlockedError);
    expect([...(err as IssueBlockedError).blockerIds].sort()).toEqual([b.id, c.id].sort());
    expect((await issueService.getIssue(t.actors.owner, t.org.id, a.id)).issue.status).toBe("backlog");

    const moveErr = await issueService
      .moveIssue(t.actors.owner, { orgId: t.org.id, issueId: a.id, toStatus: "done", toIndex: 0 })
      .catch((e: unknown) => e);
    expect(moveErr).toBeInstanceOf(IssueBlockedError);

    await issueService.changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: a.id, status: "in_review" });
    expect(seen).toEqual([a.id]);
    off();

    await issueService.changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: b.id, status: "done" });
    const stillBlocked = await issueService
      .changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: a.id, status: "done" })
      .catch((e: unknown) => e);
    expect((stillBlocked as IssueBlockedError).blockerIds).toEqual([c.id]);

    await issueService.changeIssueStatus(t.actors.owner, { orgId: t.org.id, issueId: c.id, status: "canceled" });
    const done = await issueService.changeIssueStatus(t.actors.owner, {
      orgId: t.org.id,
      issueId: a.id,
      status: "done",
    });
    expect(done.status).toBe("done");
  });
});

describe("unblocked notification", () => {
  it("notifies the assignee once when the last open blocker closes, not for closed-to-closed", async () => {
    const assignee = t.userIds.member;
    const blocked = await make("notif blocked", assignee);
    const b1 = await make("notif b1");
    const b2 = await make("notif b2");
    await depService.addBlocker(t.actors.owner, link(blocked.id, b1.id));
    await depService.addBlocker(t.actors.owner, link(blocked.id, b2.id));

    await issueService.changeIssueStatus(t.actors.admin, { orgId: t.org.id, issueId: b1.id, status: "done" });
    expect(await unblockedFor(assignee, blocked.id)).toHaveLength(0);

    await issueService.changeIssueStatus(t.actors.admin, { orgId: t.org.id, issueId: b2.id, status: "canceled" });
    const rows = await unblockedFor(assignee, blocked.id);
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({ href: `/issues/${blocked.id}`, actorId: t.actors.admin.userId, kind: "issue_unblocked" });

    await issueService.changeIssueStatus(t.actors.admin, { orgId: t.org.id, issueId: b1.id, status: "canceled" });
    expect(await unblockedFor(assignee, blocked.id)).toHaveLength(1);

    // reopen b2 and close again: unblocks and notifies again
    await issueService.changeIssueStatus(t.actors.admin, { orgId: t.org.id, issueId: b2.id, status: "todo" });
    await issueService.changeIssueStatus(t.actors.admin, { orgId: t.org.id, issueId: b2.id, status: "done" });
    expect(await unblockedFor(assignee, blocked.id)).toHaveLength(2);
  });

  it("notifies on archive of an open blocker, not of a closed one, and never on removal", async () => {
    const assignee = t.userIds.member;

    const open = await make("arch-open blocked", assignee);
    const ob = await make("arch-open blocker");
    await depService.addBlocker(t.actors.owner, link(open.id, ob.id));
    await issueService.archiveIssue(t.actors.admin, t.org.id, ob.id);
    const rows = await unblockedFor(assignee, open.id);
    expect(rows).toHaveLength(1);
    expect(rows[0]?.actorId).toBe(t.actors.admin.userId);

    const closed = await make("arch-closed blocked", assignee);
    const cb = await make("arch-closed blocker");
    await issueService.changeIssueStatus(t.actors.admin, { orgId: t.org.id, issueId: cb.id, status: "done" });
    await depService.addBlocker(t.actors.owner, link(closed.id, cb.id));
    await issueService.archiveIssue(t.actors.admin, t.org.id, cb.id);
    expect(await unblockedFor(assignee, closed.id)).toHaveLength(0);

    const removed = await make("rm blocked", assignee);
    const rb = await make("rm blocker");
    await depService.addBlocker(t.actors.owner, link(removed.id, rb.id));
    await depService.removeBlocker(t.actors.owner, link(removed.id, rb.id));
    expect(await unblockedFor(assignee, removed.id)).toHaveLength(0);
  });

  it("honours the recipient's preference and never notifies the actor", async () => {
    const member = t.actors.member;
    const blocked = await make("pref blocked", member.userId);
    const pb = await make("pref blocker");
    await depService.addBlocker(t.actors.owner, link(blocked.id, pb.id));

    await notificationService.updatePreference(member, {
      orgId: t.org.id,
      userId: member.userId,
      kind: "issue_unblocked",
      inApp: false,
      email: false,
      digestOnly: false,
    });
    await issueService.changeIssueStatus(member, { orgId: t.org.id, issueId: pb.id, status: "done" });
    expect(await unblockedFor(member.userId, blocked.id)).toHaveLength(0);

    const selfBlocked = await make("self blocked", t.userIds.admin);
    const sb = await make("self blocker");
    await depService.addBlocker(t.actors.owner, link(selfBlocked.id, sb.id));
    await issueService.changeIssueStatus(t.actors.admin, { orgId: t.org.id, issueId: sb.id, status: "done" });
    expect(await unblockedFor(t.userIds.admin, selfBlocked.id)).toHaveLength(0);
  });
});

